function tokenLore(report){
  const supply=report.supply?fmt(report.supply)+' '+(report.symbol||'tokens'):'an unreadable supply';
  const parts=[report.name+(report.symbol?' ($'+report.symbol+')':'')+' is an ERC-20 token on Robinhood Chain with '+supply+'.'];
  if(report.description)parts.push('Creator description: “'+report.description.slice(0,240)+'” This text is self-reported and unverified.');
  if(report.launch)parts.push('Pons reports a '+(report.launch.phaseLabel||'recognized')+' launch by '+short(report.launch.deployer)+' with '+(Number(report.launch.creatorTaxBps||0)/100).toFixed(2)+'% creator tax.');
  else parts.push('No Pons launch profile was available, so origin claims remain unverified.');
  if(report.activity)parts.push(report.activity.transferCount+' Transfer events involving '+report.activity.uniqueWallets+' addresses were found across the latest '+report.activity.lookbackBlocks+' blocks.');
  return parts.join(' ');
}
