  signals[1][2]=top===null||top===undefined?'Open Pepe Wallet Map to inspect relationships the holder endpoint cannot classify.':(top>=60?'High':'Moderate')+' concentration flag: '+top.toFixed(1)+'% sits in the top 10 distributed addresses. This is a clustering lead, not proof that wallets share an owner.';
