function renderSurvival(report,historyCount=0){
  if(report.riskScore===null||report.riskScore===undefined){$('survival-status').textContent='Unavailable';$('survival-note').textContent='A measurable PEPE Risk Score is required.';return;}
  const value=Math.max(0,Math.min(100,Math.round(100-report.riskScore))),coverage=Math.max(0,Math.min(100,Math.round(report.riskCoverage||0)));if(coverage<60){$('survival-status').textContent='Low evidence';$('survival-note').textContent='Directional signal withheld: '+coverage+'% evidence available, minimum 60% required. Raw score signal: '+value+'%.';return;}
  $('survival-status').textContent=value+'% score signal';
  $('survival-note').textContent='Heuristic: 100 − PEPE Risk Score. Evidence coverage: '+coverage+'%. '+historyCount+' of 7 daily snapshots collected. Not a calibrated probability.';
}
async function renderHistory(address,backend,signal,report){
  renderSurvival(report,0);
  if(!backend){$('history-status').textContent='LOCAL MODE';$('forecast-status').textContent='History unavailable';$('forecast-note').textContent='Server storage is not connected in this preview.';return 0;}
  try{const r=await fetch('/api/history?address='+encodeURIComponent(address),{signal});const data=await r.json();if(!r.ok)throw new Error();const rows=data.snapshots||[],latest=rows[0],oldest=rows.at(-1);$('history-status').textContent=rows.length?'DAILY TRACKING ACTIVE':'NO SNAPSHOTS';renderSurvival(report,rows.length);
    if(rows.length<2){$('forecast-status').textContent=rows.length?'Baseline saved':'Not tracked';$('forecast-note').textContent=rows.length?'Return on another day to measure changes in cap, holders and risk.':'The first successful analysis will create a baseline.';return rows.length;}
    const capNow=Number(latest.market_cap_usd),capThen=Number(oldest.market_cap_usd),change=capThen>0?(capNow/capThen-1)*100:null;$('forecast-status').textContent=rows.length+' daily snapshots';$('forecast-note').textContent=(change===null?'Market-cap change is unavailable.':'Market cap changed '+(change>=0?'+':'')+change.toFixed(1)+'%')+' since '+oldest.observed_day+'. Current PEPE Score: '+(latest.risk_score??'—')+'.';
    return rows.length;
  }catch(error){if(error.name==='AbortError')return 0;$('history-status').textContent='HISTORY UNAVAILABLE';$('forecast-status').textContent='Try again later';$('forecast-note').textContent='The current report is still valid, but its history could not be loaded.';return 0;}
}

function stored(key){try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value:[]}catch{return[]}}
function saveStored(key,value){localStorage.setItem(key,JSON.stringify(value))}
function watchlist(){return stored(WATCH_KEY)}
function alerts(){return stored(ALERT_KEY)}
function watched(address){return watchlist().some(item=>item.address===address.toLowerCase())}
function reportSnapshot(report){return{address:report.address.toLowerCase(),name:report.name||'Unnamed token',symbol:report.symbol||'',logoUrl:report.logoUrl||null,riskScore:report.riskScore??null,riskCoverage:report.riskCoverage??0,marketCapUsd:report.market?.marketCapUsd??null,depthUsd:report.market?.depthUsd??null,top10Pct:report.holderStats?.top10Pct??null,updatedAt:report.retrievedAt||new Date().toISOString()}}
