function renderWatchlist(){const list=watchlist(),host=$('watchlist-list');host.replaceChildren(...(list.length?list.map(item=>tokenListRow(item,{removable:true})):[emptyState('No saved tokens yet. Open any report and choose “+ Watchlist”.')]));$('watch-count').textContent=String(list.length);$('watchlist-status').textContent=list.length?list.length+' watched token'+(list.length===1?'':'s'):'Nothing to check'}
