async function directRpc(method,params){const response=await fetch(PUBLIC_RPC,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params})});if(!response.ok)throw new Error('RPC unavailable');const data=await response.json();if(data.error)throw new Error(data.error.message||'RPC unavailable');return data.result}
