function tradeDecision(report){
  const coverage=Math.round(report.riskCoverage||0),hasRisk=report.riskScore!==null&&report.riskScore!==undefined&&Number.isFinite(Number(report.riskScore)),risk=hasRisk?Number(report.riskScore):null;
  if(!hasRisk||coverage<60)return{action:'wait',label:'WAIT',reason:'Not enough verified evidence for an entry.',color:'#b8b8b3'};
  if(risk<=35)return{action:'buy',label:'BUY SETUP',reason:'Lower measured risk. Validate liquidity and size carefully.',color:'#f4f4ef'};
  if(risk<70)return{action:'wait',label:'WAIT',reason:'Mixed setup. Wait for cleaner signals.',color:'#b8b8b3'};
  return{action:'avoid',label:'AVOID',reason:'Material risks outweigh the available evidence.',color:'#ffffff'};
}
